<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';require_once __DIR__.'/../src/Finance/Invoices/InvoiceSupplierContacts.php';
use Kulturhus\Verein\{Database,InvoiceInbox,InvoiceSupplierContacts,Documents,Finance};
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);if(!Database::tableExists($db,'finance_supplier_contacts'))throw new RuntimeException('MySQL schema missing finance_supplier_contacts');
$db->exec("INSERT INTO clubs VALUES('a','A'),('b','B');INSERT INTO actors(id,club_id,role) VALUES('writer','a','members'),('cash','a','treasurer'),('member','a','member');INSERT INTO actor_capabilities VALUES('writer','local_finance');INSERT INTO contacts(id,club_id,kind,name) VALUES('firm','a','organisation','Example supplier'),('person','a','person','Example person'),('foreign','b','organisation','Foreign company');");
$n=0;function check($ok,$label){global $n;if(!$ok)throw new RuntimeException($label);++$n;echo "PASS $label\n";}function denied($f,$label){try{$f();}catch(DomainException){check(true,$label);return;}throw new RuntimeException($label);}
