$docs=new Documents($db,'writer');$inbox=new InvoiceInbox($db,'writer');$key=fn()=>bin2hex(random_bytes(16));$upload=fn()=>$docs->upload('test.xml','<Invoice xmlns="urn:synthetic:test"/>',['title'=>'Synthetic invoice','kind'=>'receipt','scope'=>'finance','links'=>[]],$key());$bill=['description'=>'Synthetic expense','counterparty'=>'Wrong text','amount'=>'12,00','category'=>'general','document_date'=>'2026-09-07','due_date'=>'2026-09-30','supplier_contact'=>'firm','supplier_version'=>'1'];$doc=$upload();$request=$key();$entry=$inbox->create($doc,1,$bill,$request,'general','R1');check((new Finance($db,'writer'))->entry($entry)['counterparty']==='Example supplier','selected name becomes initial invoice snapshot');check($service->forEntry($entry)['contact_id']==='firm','expense linked to contact');check($inbox->create($doc,1,$bill,$request,'general','R1')===$entry&&$db->query('SELECT COUNT(*) FROM finance_supplier_contacts')->fetchColumn()==1,'same save idempotent');$db->exec("UPDATE contacts SET name='Renamed supplier',version=2 WHERE id='firm'");check($service->forEntry($entry)['supplier_name']==='Example supplier','later contact rename does not overwrite invoice snapshot');$count=$db->query('SELECT COUNT(*) FROM finance_entries')->fetchColumn();denied(fn()=>$inbox->create($upload(),99,array_replace($bill,['supplier_version'=>'2']),$key(),'general','R2'),'stale original rejected');check($db->query('SELECT COUNT(*) FROM finance_entries')->fetchColumn()===$count,'original conflict rolls back expense');check(\Kulturhus\Verein\Tests\MySqlFixture::integrity($db)==='ok','database integrity');echo "$n supplier contact checks passed; isolated only\n";

